import{_ as t,o,c as a,a0 as r}from"./chunks/framework.CIWPqrYr.js";const i="/manual/assets/01-login.CNT3l6WG.png",m=JSON.parse('{"title":"1. Getting Started & Account Setup","description":"","frontmatter":{},"headers":[],"relativePath":"01-getting-started.md","filePath":"01-getting-started.md"}'),n={name:"01-getting-started.md"};function s(l,e,c,g,u,p){return o(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="_1-getting-started-account-setup" tabindex="-1">1. Getting Started &amp; Account Setup <a class="header-anchor" href="#_1-getting-started-account-setup" aria-label="Permalink to &quot;1. Getting Started &amp; Account Setup&quot;">​</a></h1><p>Welcome to Stratos! This guide will walk you through setting up your account so you can start collaborating with your team.</p><h2 id="logging-in" tabindex="-1">Logging In <a class="header-anchor" href="#logging-in" aria-label="Permalink to &quot;Logging In&quot;">​</a></h2><p>To access Stratos, navigate to your company&#39;s designated URL (e.g., <code>https://stratos.yourcompany.com</code>).</p><p><img src="'+i+'" alt="Login Screen"></p><ol><li>Enter your <strong>Email Address</strong> and <strong>Password</strong>.</li><li>If your company uses Single Sign-On (SSO) like Google or Okta, click the respective button below the main login form.</li><li>If you have forgotten your password, click the <strong>Forgot Password?</strong> link. You will receive an email with a secure link to reset it.</li></ol><h2 id="configuring-your-profile" tabindex="-1">Configuring Your Profile <a class="header-anchor" href="#configuring-your-profile" aria-label="Permalink to &quot;Configuring Your Profile&quot;">​</a></h2><p>Before diving into work, it’s best to set up your profile so your team recognizes you.</p><ol><li>Click on your avatar in the bottom-left corner of the sidebar.</li><li>Select <strong>Profile Settings</strong>.</li><li><strong>Avatar</strong>: Upload a clear photo of yourself.</li><li><strong>Name &amp; Role</strong>: Ensure your name and job title are correct.</li></ol><h3 id="notification-preferences" tabindex="-1">Notification Preferences <a class="header-anchor" href="#notification-preferences" aria-label="Permalink to &quot;Notification Preferences&quot;">​</a></h3><p>In the same settings menu, navigate to the <strong>Notifications</strong> tab. Here you can configure how Stratos alerts you:</p><ul><li><strong>Email Notifications</strong>: Toggle daily summaries or instant alerts for mentions.</li><li><strong>In-App Notifications</strong>: Choose which board events (like stage changes or new comments) trigger an alert in your Inbox.</li></ul><h3 id="appearance-themes" tabindex="-1">Appearance &amp; Themes <a class="header-anchor" href="#appearance-themes" aria-label="Permalink to &quot;Appearance &amp; Themes&quot;">​</a></h3><p>Stratos allows you to customize the platform&#39;s visual appearance to match your brand (e.g., Araneta City, Pizza Hut, Taco Bell, or a Default Monochrome).</p><ol><li>In the <strong>Profile Settings</strong> menu, navigate to the <strong>Appearance</strong> tab.</li><li>Select your preferred color theme from the swatches.</li><li>The theme will apply immediately and will be remembered on this browser, even before you log in.</li></ol>',15)])])}const d=t(n,[["render",s]]);export{m as __pageData,d as default};
